let clock = 0;
let state = "closed";
let failures = 0;
let openedAt = 0;

async function call(work) {
  if (state === "open") {
    if (clock - openedAt < 1000) return "fast-fail";
    state = "half-open";
  }
  try {
    await work();
    state = "closed";
    failures = 0;
    return "ok";
  } catch {
    failures++;
    if (state === "half-open" || failures >= 2) {
      state = "open";
      openedAt = clock;
    }
    return "error";
  }
}

