async function retry(work, attempts, isRetryable) {
  for (let attempt = 1; ; attempt++) {
    try {
      return await work(attempt);
    } catch (error) {
      if (attempt >= attempts || !isRetryable(error)) throw error;
      console.log(`attempt ${attempt} failed: ${error.message}`);
    }
  }
}

