async function withTimeout(ms, work) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(new Error("timed out")), ms);
  const aborted = new Promise((_, reject) => {
    controller.signal.addEventListener("abort", () => reject(controller.signal.reason), { once: true });
  });
  try {
    return await Promise.race([work(controller.signal), aborted]);
  } finally {
    clearTimeout(timer);
  }
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
console.log(await withTimeout(50, async () => { await sleep(5); return "fast"; }));
console.log(await withTimeout(20, async () => { await sleep(80); return "slow"; }).catch((e) => e.message));
console.log(await withTimeout(20, async (signal) => {
  await sleep(40);
  return signal.aborted ? "saw the abort" : "missed it";
}).catch((e) => e.message));

