function createBreaker(maxFailures, openMs, now) {
  let state = "closed";
  let failures = 0;
  let openedAt = 0;
  return {
    state: () => state,
    async call(work) {
      if (state === "open") {
        if (now() - openedAt < openMs) throw new Error("open");
        state = "half-open";
      }
      try {
        const result = await work();
        state = "closed";
        failures = 0;
        return result;
      } catch (error) {
        failures++;
        if (state === "half-open" || failures >= maxFailures) {
          state = "open";
          openedAt = now();
        }
        throw error;
      }
    },
  };
}

let clock = 0;
const breaker = createBreaker(2, 100, () => clock);
const down = async () => { throw new Error("503"); };
const up = async () => "ok";
const run = (work) => breaker.call(work).catch((e) => e.message);

const log = [await run(down), await run(down), await run(up)];
clock = 150;
log.push(await run(up), await run(up));
console.log(log.join(" "), breaker.state());

