function readyStatus(checks, lifecycle) {
  const reasons = Object.entries(checks).filter(([, ok]) => !ok).map(([name]) => name);
  if (lifecycle !== "running") reasons.push(`state=${lifecycle}`);
  return reasons.length === 0 ? "200" : `503 ${reasons.join(", ")}`;
}

