function priceLabel(kobo, rate, now) {
  const naira = kobo / 100;
  const fresh = rate !== undefined && now - rate.at <= 3_600_000;
  return `₦${naira.toFixed(2)}${fresh ? ` (about GH₵${(naira / rate.ngnPerGhs).toFixed(2)})` : ""}`;
}

